<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_table_names() { global $wpdb; return array( 'reports' => $wpdb->prefix . 'sd_reports', 'actions' => $wpdb->prefix . 'sd_report_actions', 'blocks' => $wpdb->prefix . 'sd_blocks', 'restrictions' => $wpdb->prefix . 'sd_restrictions', 'audit' => $wpdb->prefix . 'sd_audit_log' ); }
function sd_core_install_schema() { global $wpdb; require_once ABSPATH . 'wp-admin/includes/upgrade.php'; $t = sd_core_table_names(); $charset = $wpdb->get_charset_collate(); $sql = array(); $sql[] = "CREATE TABLE {$t['reports']} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, reporter_id bigint(20) unsigned NOT NULL, target_type varchar(32) NOT NULL, target_id bigint(20) unsigned NOT NULL, reason varchar(64) NOT NULL, description text NOT NULL, status varchar(20) NOT NULL DEFAULT 'pending', assigned_to bigint(20) unsigned NOT NULL DEFAULT 0, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY (id), KEY target (target_type,target_id), KEY status (status), KEY reporter (reporter_id)) $charset;"; $sql[] = "CREATE TABLE {$t['actions']} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, report_id bigint(20) unsigned NOT NULL, actor_id bigint(20) unsigned NOT NULL, action varchar(64) NOT NULL, note text NOT NULL, created_at datetime NOT NULL, PRIMARY KEY (id), KEY report (report_id), KEY actor (actor_id)) $charset;"; $sql[] = "CREATE TABLE {$t['blocks']} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, blocker_id bigint(20) unsigned NOT NULL, blocked_id bigint(20) unsigned NOT NULL, created_at datetime NOT NULL, PRIMARY KEY (id), UNIQUE KEY relationship (blocker_id,blocked_id), KEY blocked (blocked_id)) $charset;"; $sql[] = "CREATE TABLE {$t['restrictions']} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, user_id bigint(20) unsigned NOT NULL, restriction_type varchar(64) NOT NULL, reason text NOT NULL, applied_by bigint(20) unsigned NOT NULL, starts_at datetime NOT NULL, expires_at datetime NULL, active tinyint(1) NOT NULL DEFAULT 1, PRIMARY KEY (id), KEY user_type (user_id,restriction_type), KEY active (active)) $charset;"; $sql[] = "CREATE TABLE {$t['audit']} (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, actor_id bigint(20) unsigned NOT NULL, action varchar(64) NOT NULL, target_type varchar(32) NOT NULL, target_id bigint(20) unsigned NOT NULL, report_id bigint(20) unsigned NOT NULL DEFAULT 0, outcome varchar(32) NOT NULL, reason text NOT NULL, created_at datetime NOT NULL, PRIMARY KEY (id), KEY target (target_type,target_id), KEY report (report_id), KEY created_at (created_at)) $charset;"; foreach ( $sql as $statement ) { dbDelta( $statement ); } update_option( 'sd_core_schema_version', '1.0.0', false ); }
